fun higherDividend(x: Long, divider: Long): Long {
    return (x / divider) * divider
}

fun main() {
    val (cnt1, cnt2, x, y) = readLine()!!.split(' ').map { it.toLong() }
    var count = 0L
    var barrier = cnt1 + cnt2
    while (count != cnt1 + cnt2) {
        val xy = x * y
        var bad = higherDividend(barrier, xy) / xy
        val xCountCommon = higherDividend(barrier, y) / y - bad
        val yCountCommon = higherDividend(barrier, x) / x - bad
        val xCount = minOf(xCountCommon, cnt1)
        val yCount = minOf(yCountCommon, cnt2)
        if (xCount < xCountCommon) bad += xCountCommon - xCount
        if (yCount < yCountCommon) bad += yCountCommon - yCount
        val good = barrier - bad - xCount - yCount
        count = good + xCount + yCount
        barrier += cnt1 + cnt2 - count
    }
    print(barrier)
}

